n_basis":"lane"},{"name":"Rondón + coconut cuisine","tier":"essential","source":"https://colombiaone.com/2025/09/02/colombia-food-san-andres/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","si":"culture","blurb":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","when":"Dec–Apr","commission":"food-tour affiliate + restaurant","wells":["activities","eat"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Morgan''s Cave","tier":"essential","source":"https://colombiaone.com/2023/12/21/guide-visit-san-andres-island-colombia/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","si":"culture","blurb":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","when":"Dec–Apr","commission":"island-tour affiliate + entry (non-comm)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What are the best beaches and cays on San Andrés?","a":"Johnny Cay is the headline — a protected 4-ha coral islet ~1.5 km off San Andrés Town with the best white sand around, reached by colectivo boat — plus calm snorkel pools at La Piscinita and West View, and mellow Rocky Cay off San Luis. The lagoon is the famed \"Sea of Seven Colors.\"","source":"lonelyplanet.com, 2026-07-07","si_tag":"tropical","accessed":"2026-07-07"},{"q":"Is San Andrés good for scuba diving?","a":"Yes — it''s a shallow-water reef diver''s dream, with 40+ dive sites mostly at ~10–12 m, high-visibility and beginner-friendly, run through island PADI centers like Banda and Sharky. Providencia adds wall diving on the third-largest barrier reef in the world. Note it''s day-boat reef diving, not liveaboard-berth product.","source":"divescover.com, 2026-07-07","si_tag":"liveaboard","accessed":"2026-07-07"},{"q":"Is Providencia good for a quiet honeymoon?","a":"Yes — Providencia is the quiet-honeymoon jewel: near-empty coves, the McBean Lagoon marine park, and Crab Cay (its #1 snorkel spot, ~USD $6 park fee) reached by express boat. It''s rebuilt and open after Hurricane Iota (2020); reach it by ~20-minute inter-island flight or catamaran.","source":"cuppatocopatravels.com, 2026-07-07","si_tag":"romance","accessed":"2026-07-07"},{"q":"What language and culture will I find on San Andrés?","a":"A living Raizal Afro-Caribbean nation: 20,000–30,000 people speak San Andrés–Providencia Creole (Islander English) and most are trilingual, descended from 18th-century Jamaican settlers and enslaved Africans. The signature plate is rondón — fish, conch and root vegetables simmered in coconut milk.","source":"en.wikipedia.org, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"What''s the real day-to-day risk on the island?","a":"Not the mainland headlines — the island''s real risks are petty/beach theft, motorcycle snatch-and-grab, scooter accidents and sea/riptide hazards. Renting a scooter or golf cart is the classic island loop, and scooter crashes plus snatch-and-grab are the two most common tourist mishaps: helmet on, valuables off the seat, drive in daylight.","source":"travelsafe-abroad.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"}],"seo":{"meta_title":"San Andrés & Providencia, Colombia — Sea of Seven Colors Diving, Beaches & Raizal Culture | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-CO","local_keywords":["San Andrés qué hacer","buceo San Andrés","Providencia","tarjeta de turismo San Andrés","Johnny Cay San Andrés","Cueva de Morgan","rondón San Andrés"],"hreflang":["en","es-CO"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","source_updated":"2026-08-18T15:51:11+01:00"}]},"content_freshness":"2026-07-07","long_tail":["things to do in San Andres Colombia","San Andres diving Sea of Seven Colors","is San Andres safe 2026","Providencia island Colombia guide","San Andres tourist card cost 2026","Johnny Cay day trip San Andres","Providencia Crab Cay snorkeling"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["tropical","Dive Liveaboards / Diving","romance","culture"],"ultra":[{"name":"Casa Harb","type":"design boutique — island top-end (luxury, NOT palace-ultra)","routing":"Fora/Virtuoso preferred where participating + host","tier":"luxury"},{"name":"Decameron cluster (Isleño/San Luis/Los Delfines/Aquarium)","type":"mass-market all-inclusive","routing":"Online-Agency (OA) lane + host","tier":"premium (mass AI)"},{"name":"GHL Sunrise Hotel (Sunrise Beach)","type":"mid-market beachfront workhorse, Spratt Bight","routing":"GDS/bedbank + host","tier":"premier"},{"name":"Casa Iguana del Mar (villa)","type":"award-winning design villa, reef + white sand","routing":"MoR villa + host","tier":"luxury (thin)"},{"name":"Deep Blue (Providencia)","type":"boutique standout, Crab Cay gateway","routing":"direct/host","tier":"premium (remote boutique)"}],"source_verified":null,"hero":{"query":"San Andrés & Providencia, Colombia, Colombia"},"geo":{"lat":12.5847,"lng":-81.7006},"orbit":[{"id":"cartagena-colombia","jewels":12,"si":["romance","tropical","culture"]}],"orbit_country":["bogota-colombia","medellin-colombia"]}'::jsonb, 100),
  ('san-blas-guna-yala-panama', '10S', 'San Blas / Guna Yala, Panama', 'Panama', 'Guna Yala, island by island', 'live', 'verified', 'tropicalBeach', 'Panama', '{"tropical","romance","expedition","culture"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_date":"2024-09-23 (reissued; verified live 2026-07-07)","air_access_verified":"Charter flights Albrook (PAC) → El Porvenir (PVE) / Corazón de Jesús (CZJ), ~40–45 min, ~$400/pax; OR 4x4 (steep rain-sensitive Cartí road, ~4–5 hrs) + boat, through Guna Cartí checkpoint (passport + ~$20/pax foreigner entry fee, cash, no ATMs)","remote_flag":true,"medevac_note":"No hospital in Guna Yala; most cays have no clinic; serious cases require medevac to Panama City / US (can exceed $50,000) — comprehensive medevac insurance mandatory","health_note":"Year-round dengue/malaria/zika/chikungunya risk; malaria-risk area — consult travel clinic on prophylaxis; drink bottled/treated water","gate_result":"Verified live 2026-07-07.","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/panama","read":"2026-09-01T16:21:21Z","page_updated":"2025-12-10T13:26:25+00:00","source_country":"panama","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"dry season Dec–Apr (calmer seas for sailing + the Colombia crossing)","inflection":"Oct–Nov (winter-escape + honeymoon + dry-season sailing dates on sale)","fire_date":"mid-to-late September (curve-start − 1–2 weeks); charters sell out ahead","off_season_specials":"May–Nov green/rainy — value + solitude window, weather-tolerant travelers"},"jewels":[{"name":"Cayos Holandeses (Dutch Cays) sandbar","tier":"comfort","source":"https://www.seasanblas.com/blog/cayos-holandeses-one-of-the-best-san-blas-islands-to-visit","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the remote outer cluster — is widely rated the best snorkeling in the San Blas archipelago","si":"tropical","blurb":"the remote outer cluster — is widely rated the best snorkeling in the San Blas archipelago","when":"dry season Dec–Apr","commission":"multi-day charter / premium day-trip via DMC","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"culture":"destination","expedition":"evidenced","romance":"destination","tropical":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical/Beaches","si_map_basis":"normalised from free text ''Tropical/Beaches'' by gen_normalise_jewel_si"},{"name":"Natural Pool / Starfish spot (Piscina Natural)","tier":"essential","source":"https://www.seasanblas.com/blog/complete-guide-to-visiting-san-blas-islands-panama","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"dry season Dec–Apr","commission":"island-hopping day tour via DMC","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''island-hopping day tour via dmc''","si_all":["tropical"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"destination","tropical":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical/Beaches","si_map_basis":"normalised from free text ''Tropical/Beaches'' by gen_normalise_jewel_si"},{"name":"Isla Pelícano / Cayos Limones lagoon","tier":"essential","source":"https://nomadsailors.com/blog/cayos-limones/","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"dry season Dec–Apr","commission":"day tour / short cabaña stay","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''day tour / short cabaña stay''","si_all":["tropical"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Tropical/Beaches","si_map_basis":"normalised from free text ''Tropical/Beaches'' by gen_normalise_jewel_si"},{"name":"Castaway-island overnight cabaña","tier":"essential","source":"https://www.tripadvisor.com/Hotels-g298434-San_Blas_Islands_Guna_Yala_Region-Hotels.html","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"dry season Dec–Apr","commission":"DMC cabaña package or private charter overnight","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","tropical"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"primary","tropical":"evidenced"},"commission_lane":["DMC","package"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Isla Perro (Dog Island) wreck snorkel","tier":"essential","source":"https://sanblasadventures.com/san-blas-snorkeling/","si":"expedition","commission":"day tour / charter stop","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"culture":"destination","expedition":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Panama → Cartagena sailing charter (3–5 days)","tier":"comfort","source":"https://sanblasadventures.com/boat-colombia-to-panama/general-information/","si":"expedition","commission":"charter / CLIA lane — highest-value bookable in region","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary","romance":"destination","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Guna mola textiles + living culture (1925 revolution, matrilineal congress, Dulegaya)","tier":"essential","source":"https://www.tourismpanama.com/culture-cuisine/indigenous-communities/guna/","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"dry season Dec–Apr","commission":"cultural add-on / community visit via DMC (direct artisan purchases non-commissionable)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''cultural add-on / community visit via dm''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination","tropical":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Culture & Heritage (future)","si_map_basis":"normalised from free text ''Culture & Heritage (future)'' by gen_normalise_jewel_si"}],"faq":[{"q":"What''s the real risk to plan for in San Blas?","a":"Remoteness, not crime. There is no hospital and, on most cays, no clinic; serious illness or injury means evacuation to Panama City or the US, which can exceed $50,000. Comprehensive travel + medevac insurance is a condition of going, not an option — and dengue/malaria risk is year-round.","source":"smartraveller.gov.au, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"Are the boat crossings and the 4x4 access road dangerous?","a":"Manageable but weather-governed. Everything moves by open boat, so insist on worn life vests, a licensed captain, and a real forecast check; the Colombia passage is 24–52 hours at open sea with no turning back mid-crossing. The overland Cartí route is a steep, rain-sensitive mountain road needing a 4x4 (4–5 hours). Guided only.","source":"sanblasadventures.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"Which San Blas islands are best for beaches and snorkeling?","a":"The outer Cayos Holandeses (Dutch Cays) are widely rated the best snorkeling in the archipelago, with healthy reef and cushion starfish on the flats. Isla Perro holds the signature shallow-shipwreck snorkel a few metres from shore, while the Cayos Limones lagoon (Isla Pelícano, of *Money Heist* fame) offers the easiest crystal-shallow day-trip.","source":"seasanblas.com, 2026-07-07","si_tag":"tropical","accessed":"2026-07-07"},{"q":"Is San Blas good for a honeymoon?","a":"Yes, if you want elemental over polished. The set-piece is a private or near-private sand-cay cabaña — hammock, palm, reef at the doorstep, no wifi — from ~$56–$100/night full-board, scaling up to a private crewed catamaran overnight. Expect solar power and often no running water: this is the Caribbean before anyone built a lobby on it.","source":"tripadvisor.com, 2026-07-07","si_tag":"romance","accessed":"2026-07-07"},{"q":"What is the Panama-to-Cartagena sailing trip like?","a":"It''s a genuine passage, not a lagoon cruise. Three days threading the San Blas cays, then 24–52 hours of open-water crossing to Colombia; shared cabins run ~$525–$750 (meals + immigration paperwork included), private from ~$900+. Small boats have limited cabins and sell out weeks ahead for dry-season departures.","source":"sanblasadventures.com, 2026-07-07","si_tag":"expedition","accessed":"2026-07-07"},{"q":"Who are the Guna, and how do I enter the comarca?","a":"You enter on Guna terms. The Guna are a matrilineal people who won semi-autonomy in the 1925 revolution and still govern by congress under saila leaders; entry means a passport check and a per-person cash fee (~$20/foreigner) at the Cartí checkpoint, with no ATMs on the islands. Buy reverse-appliqué molas direct from the women who sew them.","source":"ampatours.com, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"}],"seo":{"meta_title":"San Blas Islands (Guna Yala), Panama — Castaway Cays, Sailing & the Guna | TravelWell.World","search_language":"es-PA","local_keywords":["San Blas Guna Yala","islas San Blas Panamá","velero San Blas Cartagena","cómo llegar a San Blas desde Ciudad de Panamá","cabañas San Blas Guna Yala","molas guna","Cayos Holandeses"],"hreflang":["en","es-PA"],"jsonld_type":"TouristDestination","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/panama","read":"2026-08-20T14:55:13Z","source_updated":"2025-12-10T13:26:25+00:00"}]},"content_freshness":"2026-07-07","long_tail":["how to get to San Blas islands from Panama City","San Blas to Cartagena sailing trip","best San Blas islands for snorkeling","Isla Perro shipwreck snorkel","private catamaran charter San Blas","is San Blas Panama safe"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":null,"ultra":[{"type":"private crewed catamaran","name":"ZENITH / CruiseSanBlas / Charter in San Blas","note":"the luxury vehicle in Guna Yala — no branded ultra property exists","earning":"private-charter / CLIA lane"},{"type":"Panama City bookend hotel","name":"American Trade Hotel (Casco Viejo, Small Luxury Hotels of the World)","note":"consortia/Virtuoso-adjacent luxury anchor for the city night","earning":"Fora / consortia hotel commission"}],"source_verified":null,"hero":{"query":"San Blas / Guna Yala, Panama, Panama"},"geo":{"lat":9.57,"lng":-78.95},"orbit":[{"id":"bocas-del-toro-panama","jewels":13,"si":["tropical","diveglobal","romance","adventure"]},{"id":"panama-city-panama","jewels":10,"si":["culture","river","romance","adventure","culinary"]},{"id":"boquete-panama","jewels":8,"si":["expedition","culinary"]}],"orbit_country":[]}'::jsonb, 101),
  ('san-cristobal-de-las-casas-mexico', '10S', 'San Cristóbal de las Casas, Mexico', 'Mexico', 'San Cristóbal de las Casas', 'live', 'verified', 'kyoto', 'Chiapas (San Cristóbal & Palenque)', '{"culture","expedition"}', '{}', '{"essential","comfort","luxury","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_named_area_language":"US govt employees may travel to Tapachula (city limits, S/W of Hwy 200); may NOT travel to municipality of Ocozocoautla; may NOT travel to Southeastern Chiapas polygon (Guatemala border Pacific->Netzahualcoyotl->Ocosingo->El Ocote->San Francisco Pujiltic->Mapastepec, E/N of Hwy 200). San Cristobal / Tuxtla / Chiapa de Corzo fall OUTSIDE named boundaries.","gate_decision":"BOOK WITH WARNING","air_access_verified":true,"air_access_note":"Tuxtla Gutierrez TGZ (Angel Albino Corzo Intl) ~77km / ~1h05-1h30 to San Cristobal via Hwy 190/190D; corridor outside restricted zone","road_safety_flag":"Hwy 199 San Cristobal<->Palenque via Ocosingo: reported armed robbery (mostly night) + CNTE blockades — daytime-only, guided/private transfer","altitude":"~2200m, mild","water":"bottled/purified only","dengue":"lowland concern (Palenque/jungle/canyon), not highland city","founder_attorney_flag":"consent-flow wording pending compliance-attorney sign-off; re-verify advisory before each fire and before live checkout","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":["Nov-Apr dry season","Dia de Muertos (Oct 31-Nov 2)","Semana Santa (2026: Mar 29-Apr 5)"],"inflection":"6-10 weeks pre-peak; boutique tier sells 8-12 weeks out","fire_date":"curve-start minus 1-2 weeks (dry-season fire ~mid-Sep; Dia de Muertos fire ~early-mid Oct","off_season_specials":"May-Oct green/rainy value window; culture fully accessible year-round; highland climate never hot"},"jewels":[{"name":"Andadores + Templo de Santo Domingo + Museo del Ámbar","tier":"essential","source":"https://randomtrip.net/san-cristobal-de-las-casas-travel-guide-chiapas-mexico/","timing":"[''Nov-Apr dry season'', ''Dia de Muertos '', ''Semana Santa '']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"[''Nov-Apr 