ext","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary","romance":"destination"},"commission_lane":["DMC","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Xunantunich + El Castillo + hand-cranked ferry","tier":"essential","source":"https://www.nayawalk.com/belize/xunantunich/","hook":"The Classic Maya city sits near the Belize–Guatemala border","si":"culture","blurb":"The Classic Maya city sits near the Belize–Guatemala border","commission":"DMC half-day / lodge tour","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination"},"commission_lane":["DMC","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Caracol — Caana (Belize''s tallest structure)","tier":"premier","source":"https://trans-americas.com/caracol-archaeological-site-belize/","timing":"Dec-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Reached only by military-escorted convoy from the Douglas D''Silva Forest Station because of Guatemala-border proximity","si":"culture","blurb":"Reached only by military-escorted convoy from the Douglas D''Silva Forest Station because of Guatemala-border proximity","when":"Dec-Apr dry season","commission":"licensed DMC full-day + convoy logistics","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cahal Pech (walking distance from town)","tier":"essential","source":"https://www.stleonardsbelize.com/belize-tours/xunantunich-cahal-pech-tour","timing":"Dec-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec-Apr dry season","commission":"self-guided fee / add-on guided walk","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tikal day-trip (Guatemala)","tier":"premier","source":"https://www.pacztours.net/","timing":"Dec-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec-Apr dry season","commission":"licensed DMC full-day cross-border","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''licensed dmc full-day cross-border''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Green Iguana Conservation Project","tier":"essential","source":"https://www.sanignaciobelize.com/green-iguana-conservation-project/","timing":"Dec-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dec-Apr dry season","commission":"in-town lodge activity / affiliate","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''in-town lodge activity / affiliate''","si_all":["romance","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"primary","wildlife":"evidenced"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Romance & Nature","si_map_basis":"normalised from free text ''Romance & Nature'' by gen_normalise_jewel_si"},{"name":"Belize Botanic Gardens at du Plooy''s","tier":"essential","source":"https://www.sanignaciobelize.com/","si":"romance","commission":"lodge stay / day visit / bedbank","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"primary","wildlife":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Romance & Nature","si_map_basis":"normalised from free text ''Romance & Nature'' by gen_normalise_jewel_si"},{"name":"Chaa Creek Butterfly Farm + Macal River canoe","tier":"comfort","source":"https://chaacreek.com/","timing":"Dec-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dec-Apr dry season","commission":"lodge stay + activity","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''lodge stay + activity''","si_all":["romance","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"primary","wildlife":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Romance & Nature","si_map_basis":"normalised from free text ''Romance & Nature'' by gen_normalise_jewel_si"},{"name":"Spanish Lookout (Mennonite community)","tier":"essential","source":"https://www.lonelyplanet.com/belize/western-belize/san-ignacio-cayo/attractions/green-iguana-conservation-project/a/poi-sig/460812/358218","timing":"year-round","timing_type":"ALWAYS-ON","si":"romance","when":"year-round","commission":"DMC add-on / self-drive","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","romance":"primary","wildlife":"evidenced"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Romance & Nature","si_map_basis":"normalised from free text ''Romance & Nature'' by gen_normalise_jewel_si"}],"faq":[{"q":"What is the ATM cave tour like, and do you need a guide?","a":"It is the apex Cayo adventure and it is guided-only by law — you cannot legally enter Actun Tunichil Muknal without a licensed operator. Expect a ~45-minute jungle trek with multiple river crossings, a swim into the cave mouth, wading a shallow underground river in total darkness, and tight climbs; ~3 hours inside. Cameras have been banned since a 2012 incident cracked a ~1,000-year-old skull.","source":"en.wikipedia.org, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"How do you visit Caracol and Xunantunich?","a":"Differently. Caracol — whose Caana pyramid (141 ft/43 m) is Belize''s tallest structure — requires a military-escorted convoy from the Douglas D''Silva Forest Station (muster ~9 am, return ~2 pm) because it sits near the porous Guatemala border. Xunantunich is easier: a 20-minute drive and a hand-cranked Mopan River ferry to El Castillo, ~40 m and the country''s second-tallest structure.","source":"trans-americas.com, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Is San Ignacio good for a honeymoon?","a":"Yes — for jungle romance rather than beach. The luxury lodge belt is world-class: Coppola''s Blancaneaux Lodge (~20 rooms, Mountain Pine Ridge waterfalls), the 500-acre Green Globe reserve at Chaa Creek (founded 1981, with butterfly farm, spa and Macal River canoeing), and Ka''ana''s plunge-pool villas. Plunge-pool casitas, canopy dinners and waterfall spas define the market.","source":"chaacreek.com, 2026-07-06","si_tag":"romance","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for in Cayo?","a":"Water, wildlife and inland health, not urban crime. CDC advises avoiding swimming in fresh, unchlorinated water (leptospirosis), yet ATM and cave-tubing involve unavoidable river immersion, so treat them as guided-only informed-consent activities; high water after heavy rain periodically closes the caves. CDC also states malaria is a risk in some parts of Belize — treat the mainland jungle as potential risk and get a travel-medicine consult; dengue is present.","source":"wwwnc.cdc.gov, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"Is the ATM cave tour dangerous?","a":"It is physically demanding but safe as a licensed, guided activity — there is no legal or safe self-tour option. The tour requires \"good to very good\" fitness for river fordings, swimming into the cave, and tight passages and climbs in the upper chambers, with a minimum height of ~40 inches. Cave-tubing and Barton Creek Cave are likewise licensed-guide-required, with rising-water hazard after rain.","source":"chaacreek.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"San Ignacio & Cayo, Belize: ATM Cave, Xunantunich, Caracol & Jungle Lodges | TravelWell.World","meta_description":"Belize''s inland adventure capital — swim into the Crystal Maiden''s cave, climb Caracol and Xunantunich, sleep in Coppola''s jungle hideaway. Guided-only cave tours, luxury eco-lodges, how to travel Cayo well.","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en","local_keywords":["San Ignacio Belize","Cayo District adventure","ATM cave tour","Actun Tunichil Muknal Crystal Maiden","Xunantunich hand-cranked ferry","Caracol military convoy","Blancaneaux Lodge Belize","cave tubing Belize","best jungle lodges San Ignacio","is Cayo Belize safe 2026"],"hreflang":["en","es-419 (optional)"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-08-20T14:53:57Z","source_updated":"2026-06-12T10:40:30+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["expedition","Culture & Heritage (future)","romance"],"ultra":[{"name":"Blancaneaux Lodge","why":"~20-room Coppola hideaway, Mountain Pine Ridge, waterfall pools","earning_path":"Family Coppola Hideaways direct + consortia/Fora lane","mor":"direct-to-lodge","tier":"$$$$"},{"name":"Ka''ana Resort","why":"18 suites/villas, private plunge pools, boutique 17-acre estate","earning_path":"consortia/Fora + direct","mor":"direct","tier":"$$$-$$$$"},{"name":"The Lodge at Chaa Creek","why":"500-acre Green Globe reserve, Macal River, spa, villas","earning_path":"direct + advisor consortia","mor":"direct/AOR","tier":"$$$-$$$$"},{"name":"Gaïa Riverlodge","why":"Small Luxury Hotels of the World; 16 cabanas atop Five Sisters Falls, hydropowered","earning_path":"SLH channel + consortia","mor":"SLH/direct","tier":"premier"},{"name":"Table Rock Jungle Lodge","why":"intimate boutique Macal-riverfront cabañas","earning_path":"direct commission","mor":"direct","tier":"comfort"}],"source_verified":"2026-07-06","hero":{"query":"San Ignacio / Cayo, Belize, Belize"},"geo":{"lat":17.1598,"lng":-89.0714},"orbit":[{"id":"ambergris-caye-belize","jewels":11,"si":["tropical","liveaboard","romance","expedition"]},{"id":"blue-hole-belize","jewels":8,"si":["liveaboard","expedition","tropical"]},{"id":"caye-caulker-belize","jewels":9,"si":["tropical","liveaboard","expedition","ocean","culinary"]},{"id":"hopkins-belize","jewels":8,"si":["tropical","expedition","culture"]},{"id":"placencia-belize","jewels":8,"si":["liveaboard","expedition","diveglobal","ocean","wildlife","culture"]}],"orbit_country":[]}'::jsonb, 103),
