":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Dolores Hidalgo — independence + nieves exóticas","status":"future","hook":"Birthplace of Mexican independence + famous exotic ice creams (tequila, avocado, shrimp)","bookable_category":"day trip (paired w/ Atotonilco)","tier":"comfort","source":"https://epicureanexpats.com/dolores-hidalgo-and-atotonilco/ (Accessed 2026-07-05)","timing":"Wedding waves Oct–Nov and Mar–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Birthplace of Mexican independence + famous exotic ice creams (tequila, avocado, shrimp)","when":"Wedding waves Oct–Nov and Mar–May","commission":"activity affiliate / DMC","accessed":"2026-07-05","wells":["activities","eat"],"wells_basis":"full pass 2026-10-05, additive — bookable_category + food SI (David 2026-10-05: every traveler has to eat)","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","romance":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"La Gruta hot springs","status":"future","hook":"Thermal pools reached through a lit volcanic cave tunnel, ~20 min out","bookable_category":"entry + transfer or spa package","tier":"comfort","source":"https://mexicotravel.blog/la-gruta-spa-hot-springs-san-miguel-de-allende/ (Accessed 2026-07-05)","si":"wellness","blurb":"Thermal pools reached through a lit volcanic cave tunnel, ~20 min out","commission":"activity affiliate / DMC","accessed":"2026-07-05","wells":["move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wellness"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"destination","wellness":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Temazcal ceremony","status":"future","hook":"Pre-Hispanic sweat-lodge ritual — authentic wellness with cultural depth","bookable_category":"guided ceremony (hotel or specialist)","tier":"premier","source":"https://mexicotravel.blog/la-gruta-spa-hot-springs-san-miguel-de-allende/ (Accessed 2026-07-05)","timing":"Wedding waves Oct–Nov and Mar–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wellness","blurb":"Pre-Hispanic sweat-lodge ritual — authentic wellness with cultural depth","when":"Wedding waves Oct–Nov and Mar–May","commission":"activity affiliate / hotel spa","accessed":"2026-07-05","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wellness"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"destination","wellness":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for?","a":"The southern industrial corridor, plus altitude and cobblestones. In town, the practical notes are a high-desert **~1,900 m** altitude (mild first-day effects) and steep cobblestone streets; Hospital MAC handles ER/ICU care, with advanced-trauma evac to Querétaro (~1 hr).","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"Is SMA good for a destination wedding, and how far ahead do I book?","a":"Yes — it''s Mexico''s wedding capital, with a decades-deep planner/vendor ecosystem and venues for **20–300 guests**. The lead time is long: serious venue/planner inquiry runs **6–12 months** before the date, with the **Oct–Nov and Mar–May** weekends going first, so fire villa blocks a full engagement season ahead.","source":"destinationweddings.com, 2026-07-05","si_tag":"romance","accessed":"2026-07-05"},{"q":"What are the must-see culture sites?","a":"The pink Parroquia de San Miguel Arcángel over the Jardín, the UNESCO historic center, the Fábrica La Aurora art complex, and — ~15 min north — the Santuario de Atotonilco (1740–1776), the \"Sistine Chapel of the Americas,\" with six chapels of floor-to-ceiling baroque murals.","source":"viator.com, 2026-07-05","si_tag":"culture","accessed":"2026-07-05"},{"q":"What''s the wellness scene?","a":"Thermal and ceremonial. La Gruta''s hot springs run **37–40 °C**, reached through a ~20 m lit volcanic cave tunnel, and temazcal (pre-Hispanic sweat-lodge) ceremonies pair with hotel-spa culture like Belmond''s Laja Spa — honeymoon-ready restoration.","source":"mexicotravel.blog, 2026-07-05","si_tag":"wellness","accessed":"2026-07-05"},{"q":"Is there a wine route?","a":"Yes — the under-the-radar Guanajuato wine route an hour from town, anchored by Cuna de Tierra (the state''s oldest winery) and Viñedos San Miguel, and paired with Dolores Hidalgo''s independence history and famous *nieves exóticas* (exotic ice creams).","source":"mexicotravelandleisure.com, 2026-07-05","si_tag":"culinary","accessed":"2026-07-05"}],"seo":{"meta_title":"San Miguel de Allende Travel & Wedding Guide — World''s Best Small City | TravelWell.World","meta_description":"The world''s ''Best Small City'' and Mexico''s destination-wedding capital: the pink Parroquia, hacienda + villa weddings, hot-air balloons over the Bajío, Atotonilco, Dolores Hidalgo, the Guanajuato wine route.","slug":"san-miguel-de-allende-mexico","primary_keyword":"San Miguel de Allende travel guide","long_tail":["San Miguel de Allende wedding venues 2026","is San Miguel de Allende safe 2026","best luxury hotels San Miguel de Allende","hot air balloon San Miguel de Allende","Atotonilco Sistine Chapel of the Americas","Dolores Hidalgo day trip","Guanajuato wine route","things to do San Miguel de Allende"],"search_language":"es-MX","local_keywords":["boda San Miguel de Allende","¿es seguro viajar a San Miguel de Allende?","hoteles de lujo San Miguel de Allende","vuelo en globo San Miguel de Allende","Santuario de Atotonilco","ruta del vino Guanajuato","qué hacer en San Miguel de Allende","nieves exóticas Dolores Hidalgo"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-05","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-05","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Rosewood San Miguel de Allende","why_ultra":"Hacienda-style flagship in a transformed 16th-c colonial building; Luna rooftop with Parroquia views; spa; top wedding property","earning":"on application / Rosewood Elite via Virtuoso/Fora","mor":true,"tier":"ultra"},{"name":"Casa de Sierra Nevada, A Belmond Hotel","why_ultra":"37 rooms across six 17th–18th-c colonial buildings; Laja Spa; UNESCO-center heritage-luxury icon + premier wedding host","earning":"on application / Belmond Bellini Club via Virtuoso/Fora","mor":true,"tier":"ultra"},{"name":"Live Aqua San Miguel de Allende","why_ultra":"Sensory-luxury adults-oriented boutique; serene design + spa; luxury-wedding/honeymoon fit","earning":"on application / host program","mor":true,"tier":"luxury"},{"name":"Hotel Matilda (Design Hotels)","why_ultra":"Contemporary Mexican design-luxury, serious art collection, glamour crowd","earning":"on application / Design Hotels / Fora lane","mor":true,"tier":"luxury-boutique"},{"name":"Numu (