  ('san-sebastian-del-oeste-mexico', '10S', 'San Sebastián del Oeste', 'Mexico', 'A fog-wrapped colonial mining town in the Sierra', 'live', 'verified', 'kyoto', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"culture","expedition","culinary"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Colonial Sierra Madre Pueblo Mágico ~65 km / 1.5–2 hr NE of Puerto Vallarta via Hwy 544 (Source: mexicotravelsecrets.com, Accessed 2026-07-04)","Settled 1605; gold-mining town into the early 20th c.; mining museum + Mina Santa Gertrudis mine cave (Source: mexicotravelsecrets.com, Accessed 2026-07-04)","~1,480 m elevation — cool (~25°C) when the coast is hot/humid (Source: mexicotravelsecrets.com, Accessed 2026-07-04)","Organic café de altura (La Quinta Mary, Hacienda Jalisco grows/roasts its own) (Source: savoteur.com, Accessed 2026-07-04)","Cerro de la Bufa viewpoint over Banderas Bay; Mexico''s #2 raicilla producer (Source: forbes.com.mx, Accessed 2026-07-04)","Small paved airstrip with light-aircraft (Cessna) day service from Puerto Vallarta (Source: puertovallarta.net, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"No trauma hospital in the mountains; nearest full ER/trauma is Puerto Vallarta (AMERIMED trauma ER, CMQ Premiere, Hospiten) ~1.5–2 hr back down winding Sierra road; air-evac to US for critical cases","air_access_verified":"via PVR ~1.5–2 hr mountain ground (not into a carve-out); small airstrip with light-aircraft day service exists — verify current schedule","malaria":"none","dengue":"lower at ~1,480 m altitude than coast; not zero — precautions in wet months","yellow_fever":"not required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"November–May (dry season, coffee harvest, clear La Bufa bay views; PV high season feeds day-trips)","shoulder":"June & October","green":"July–September (wet season, foggier/rainier mountain roads, ~1,000–1,400 mm annual)","booking_lead":"Days for a PV day-tour; 2–4+ weeks for tiny boutique hacienda rooms on winter weekends","off_season_specials":"Green-season lush Sierra + coffee-country escape from coastal heat; disclose rain + mountain-road risk","event_peaks":"PV high season (Dec–Apr), Semana Santa, coffee-harvest window (local festival dates verify)","fire_date":"Early fall into PV winter arrivals; summer ''cool-mountain escape'' value to PV visitors"},"jewels":[{"name":"Colonial center + mining museums","status":"future","hook":"Near-intact 18th-c. plaza/church + mining museum + Mina Santa Gertrudis","bookable_category":"day-tour stop / free stroll","tier":"essential","source":"https://www.mexicotravelsecrets.com/san-sebastian-del-oeste-travel-guide/ (Accessed 2026-07-04)","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Near-intact 18th-c. plaza/church + mining museum + Mina Santa Gertrudis","when":"year-round","commission":"PV day-tour or curated-recommend","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"La Quinta Mary coffee-plantation tour","status":"future","hook":"Organic café de altura, artisanal-process tour","bookable_category":"plantation tour","tier":"essential","source":"https://savoteur.com/san-sebastian-del-oeste-jalisco-mexico/ (Accessed 2026-07-04)","timing":"November–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Organic café de altura, artisanal-process tour","when":"November–May","commission":"day-tour add-on","accessed":"2026-07-04","wells":["eat","activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Culinary / Coffee","si_map_basis":"normalised from free text ''Culinary / Coffee'' by gen_normalise_jewel_si"},{"name":"Raicilla tasting","status":"future","hook":"Mexico''s #2 raicilla producer; agave-lechuguilla craft spirit","bookable_category":"tasting stop","tier":"essential","source":"https://forbes.com.mx/forbes-life/viajes-pueblo-magico-de-san-sebastia-del-oeste-en-jalisco/ (Accessed 2026-07-04)","timing":"November–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Mexico''s #2 raicilla producer; agave-lechuguilla craft spirit","when":"November–May","commission":"day-tour add-on / curated","accessed":"2026-07-04","wells":["activities","eat","shop"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Culinary / Coffee","si_map_basis":"normalised from free text ''Culinary / Coffee'' by gen_normalise_jewel_si"},{"name":"Hacienda Jalisco visit","status":"future","hook":"19th-c. hacienda that stored precious metals for Spain; grows/roasts its own coffee","bookable_category":"day-tour / boutique overnight","tier":"comfort","source":"https://www.banderasnews.com/travel-outdoors/hacienda-jalisco.htm (Accessed 2026-07-04)","timing":"November–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"19th-c. hacienda that stored precious metals for Spain; grows/roasts its own coffee","when":"November–May","commission":"curated-recommend (direct-only lodging)","accessed":"2026-07-04","wells":["stay","activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Cerro de la Bufa viewpoint + summit trail","status":"future","hook":"Short hikes to a Banderas Bay panorama + sunrise vantage","bookable_category":"guided hike / self-walk","tier":"essential","source":"https://forbes.com.mx/forbes-life/viajes-pueblo-magico-de-san-sebastia-del-oeste-en-jalisco/ (Accessed 2026-07-04)","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"Short hikes to a Banderas Bay panorama + sunrise vantage","when":"year-round","commission":"day-tour / guide","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sierra Madre forest hikes + rappelling","status":"future","hook":"Cool-mountain pine-oak forest walks + adventure","bookable_category":"licensed guide/operator","tier":"comfort","source":"https://www.mexicotravelsecrets.com/san-sebastian-del-oeste-travel-guide/ (Accessed 2026-07-04)","timing":"November–May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Cool-mountain pine-oak forest walks + adventure","when":"November–May","commission":"activity affiliate / day-tour","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Can I book a stay in San Sebastián del Oeste?","a":"No — it is content-only, recommended only as a licensed day-trip from the Puerto Vallarta carve-out.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"The mountain road transfer, not the town. The ~65 km / 1.5–2 hr drive on Hwy 544 leaves the PV safe zone through non-carve-out Sierra — the hold reason — and fog on narrow roads makes daytime, licensed transport essential. The nearest trauma hospital is ~1.5–2 hr back down in Puerto Vallarta.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"What is there to see in the colonial town?","a":"A 17th-century time capsule. Settled in 1605 for gold, San Sebastián keeps a near-intact 18th-century plaza and church, a mining museum, and the Mina Santa Gertrudis (~60 m mine cave); it is quiet and cool at ~1,480 m. Clearest touring is November–May.","source":"mexicotravelsecrets.com, 2026-07-04","si_tag":"culture","accessed":"2026-07-04"},{"q":"What''s the coffee-and-raicilla scene like?","a":"It is the town''s signature taste. The Sierra grows organic *café de altura* — La Quinta Mary is a 19th-century estate offering artisanal-process tours, and Hacienda Jalisco grows, processes and roasts its own — and San Sebastián is Mexico''s #2 raicilla producer, a craft spirit distinct from tequila.","source":"savoteur.com / forbes.com.mx, 2026-07-04","si_tag":"culinary","accessed":"2026-07-04"},{"q":"What''s the hiking like at Cerro de la Bufa?","a":"Short but remote. Cerro de la Bufa offers a viewpoint and summit trail with a panorama over Banderas Bay — the coast you left, seen from ~1,480 m and higher; go guided, start early on a clear dry-season morning, and turn back in fog, since trauma care is 1.5–2 hr away in PV.","source":"forbes.com.mx, 2026-07-04","si_tag":"expedition","accessed":"2026-07-04"}],"seo":{"meta_title":"San Sebastián del Oeste Travel Guide — Jalisco''s Colonial Coffee-Mountain Pueblo Mágico | TravelWell.World","meta_description":"Jalisco''s fog-wrapped 1605 mining town in the Sierra Madre — café de altura, raicilla, Cerro de la Bufa bay views, and accurate guidance: an interior day-trip from Puerto Vallarta, not a bookable base.","slug":"san-sebastian-del-oeste-mexico","primary_keyword":"San Sebastián del Oeste Mexico travel guide","long_tail":["day trip San Sebastián del Oeste from Puerto Vallarta","San Sebastián del Oeste coffee tour","is San Sebastián del Oeste safe","Cerro de la Bufa hike","Hacienda Jalisco San Sebastián"],"search_language":"es-MX","local_keywords":["qué hacer en San Sebastián del Oeste","San Sebastián del Oeste desde Puerto Vallarta tour de un día","café de altura San Sebastián del Oeste","raicilla San Sebastián del Oeste","Cerro de la Bufa mirador","Hacienda Jalisco San Sebastián del Oeste"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"expedition","status":"future"},{"si":"Culinary / Coffee","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"San Sebastián del Oeste, Mexico"},"geo":{"lat":20.7667,"lng":-104.8433},"orbit":[{"id":"careyes-mexico","jewels":7,"si":["ultra","romance","ocean"]},{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture","senior"]},{"id":"costalegre-mexico","jewels":7,"si":["tropical","romance","ultra","ocean"]},{"id":"guadalajara-mexico","jewels":8,"si":["culture","culinary","entertainment","sports"]},{"id":"mazamitla-mexico","jewels":6,"si":["expedition","family","adventure"]},{"id":"puerto-vallarta-mexico","jewels":5,"si":["romance","expedition","ocean"]},{"id":"tlaquepaque-mexico","jewels":4,"si":["culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","celestun-mexico","chichen-itza-mexico","coba-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 109),
