.com/tours/Mexico-City/Private-Tour-and-Hot-Air-Balloon-Flight-over-Teotihuacan/d628-366381P1 (Accessed 2026-07-05)"},{"note":"No true ultra STAY at Teotihuacán — nearest ultra stay = CDMX. Accurate tier: premier day-experience."}],"source_verified":"2026-07-05","hero":{"query":"Teotihuacán, Mexico"},"geo":{"lat":19.6925,"lng":-98.8438},"orbit":[{"id":"mexico-city-mexico","jewels":17,"si":["romance","culture","culinary","entertainment"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 117),
  ('tikal-guatemala', '10S', 'Tikal / Flores', 'Guatemala', 'Temple IV at sunrise, Peten jungle', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage Site (1979); 576 km² biosphere with 3,000+ identified Maya structures.","Temple IV rises 64.6 m (212 ft) — the tallest pre-Columbian structure in the Americas; the classic sunrise perch above the canopy.","Tikal park entry Q150 (~US$19.50) foreigners; open 06:00–18:00; sunrise/sunset permits +Q100 each (mandatory guide).","Flores/Santa Elena (FRS) Mundo Maya airport takes 4–5 daily flights from Guatemala City (GUA) on TAG Airlines & Avianca; Tikal is 65 km / ~1 hr from Flores.","Base is the island town of Flores on Lake Petén Itzá; the wildlife includes jaguars, 5 cat species, howler/spider monkeys, coatis, ocellated turkeys and 400+ birds."],"safety":{"emergency":{"police":"110","fire_ambulance":"122 / 123","tourist_assistance_PROATUR":"1500"},"hospital":"Nearest hospital in Santa Elena/Flores (~1 hr); serious cases air-evac to Guatemala City. HARD remote-medevac flag — Tikal is jungle-remote.","l3_disclosure":true,"stay_in_zone":true,"malaria":"Petén is a CDC-named P. vivax malaria chemoprophylaxis department AND an annual dengue department — pre-trip travel-medicine consult + bite prevention required","water":"Bottled/filtered only","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-09-01T16:18:35Z","page_updated":"2026-08-13T14:45:16+01:00","source_country":"guatemala","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Within 5km of the Mexican border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"The towns of Santa Ana Huista, San Antonio Huista and La Democracia, in Huehuetenango","lvl":3,"posture":"all-but-essential"}]},"timing":{"inflection_curve_start":"early-to-mid November","peak":"December–March (Semana Santa spike late Mar/early Apr; TWW best-month = January)","fire_date":"2026-10-24","shoulder":"May; late-Oct/early-Nov","green":"May–October (Sep–Oct wettest / true off-season)","booking_lead":"3–6 weeks peak; 8–12 weeks for Semana Santa (lead pressure is on beds)","off_season_specials":"green-season lodge discounts + empty-Tikal wildlife/birding positioning","event_peaks":["Semana Santa (Holy Week)","Uaxactún equinox sunrise (Mar/Sep)"]},"jewels":[{"name":"Sunrise on Temple IV (above the canopy)","status":"live","hook":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","bookable_category":"guided sunrise tour","tier":"comfort","source":"https://www.getyourguide.com/guatemala-l169110/from-flores-tikal-sunrise-archaeological-tour-t535277/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","when":"year-round","commission":"GetYourGuide/Viator affiliate; private via host-IATA land services","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition"],"shelf_fit":{"culture":"evidenced","expedition":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Waking-jungle wildlife walk","status":"live","hook":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","bookable_category":"archaeology+wildlife guided tour","tier":"comfort","source":"https://www.tripadvisor.com/Attractions-g292015-Activities-c42-Tikal_National_Park_Peten_Department.html + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","when":"December–March","commission":"GYG/Viator affiliate; DMC upsell","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition","wildlife"],"shelf_fit":{"culture":"evidenced","expedition":"primary","wildlife":"evidenced"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane","si_raw":"GEA / Wildlife","si_map_basis":"normalised from free text ''GEA / Wildlife'' by gen_normalise_jewel_si"},{"name":"Cerro Cahuí Biotope (El Remate)","status":"live","hook":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","bookable_category":"guided hike + lodge night","tier":"essential","source":"https://www.fodors.com/world/mexico-and-central-america/guatemala/el-peten/things-to-do/sights/reviews/biotopo-cerro-cahui-578646 + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","when":"December–March","commission":"host-IATA land services + lodge night","accessed":"2026-07-06","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Lake Petén Itzá boat sunset","status":"live","hook":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","bookable_category":"boat tour","tier":"essential","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","si":"expedition","blurb":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","commission":"affiliate + lodge concierge","accessed":"2026-07-06","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"ARCAS Wildlife Rescue","status":"live","hook":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","bookable_category":"visit/volunteer (local)","tier":"essential","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","when":"December–March","commission":"thin/donation-driven — goodwill add-on","accessed":"2026-07-06","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition","wildlife"],"shelf_fit":{"culture":"destination","expedition":"primary","wildlife":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"GEA / Wildlife","si_map_basis":"normalised from free text ''GEA / Wildlife'' by gen_normalise_jewel_si"},{"name":"Yaxhá sunset (Temple 216)","status":"future","hook":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","bookable_category":"guided sunset day-tour","tier":"comfort","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","when":"year-round","commission":"GYG/Viator affiliate or host-IATA land services","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Uaxactún astronomical observatory (Group E / E-VII-sub)","status":"future","hook":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","bookable_category":"private/small-group day-tour","tier":"premier","source":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8078784/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","when":"December–March","commission":"host-IATA land services (private)","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Flores island (Sky Bar sunset)","status":"future","hook":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","bookable_category":"boutique-hotel stay","tier":"essential","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","when":"December–March","commission":"hotel affiliate / host-IATA","accessed":"2026-07-06","wells":["activities","shop","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Playa Chechenal (San Miguel)","status":"future","hook":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","bookable_category":"DIY (boat/walk)","tier":"essential","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","when":"December–March","commission":"none meaningful — local-color add-on","accessed":"2026-07-06","wells":["activities","eat","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for at Tikal?","a":"Mosquito-borne disease, not crime. Petén is a CDC-named malaria (*P. vivax*) prophylaxis department and reports dengue annually — so book a travel-medicine consult before departure, use DEET/picaridin, cover up at dawn/dusk, and choose screened or AC rooms.","source":"cdc.gov Yellow Book, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"How remote is Tikal if something goes wrong?","a":"Genuinely remote — plan for it. The nearest hospital is in Santa Elena/Flores (~1 hr from the park); anything serious means air evacuation to Guatemala City, so travel medical + medevac insurance is not optional here. Save the PROATUR tourist-assistance line (1500).","source":"livinginguatemala.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"Is the Tikal sunrise tour worth the 3 a.m. start?","a":"For most, yes — it''s the signature. You leave Flores around 3 a.m. for the ~45–60 min / 65 km drive, enter at 4 a.m. with a mandatory guide, and climb the 212 ft Temple IV to watch dawn break over the canopy as howler monkeys roar in. Skip it only if you can''t manage steep wooden stairs in the dark.","source":"getyourguide.com / livinginguatemala.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Do I need a guide at Tikal, and is Yaxhá worth adding?","a":"Hire a guide — without one Tikal is impressive but confusing (group ~US$39–65, private ~US$65–104). For a quieter Maya sunset, add Yaxhá: Guatemala''s third-largest site over twin lagoons, about half Tikal''s entry fee, far fewer people.","source":"livinginguatemala.com / indietraveller.co, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"What wildlife will I actually see at Tikal?","a":"On a dawn/wildlife-focus walk, reliably: howler and spider monkeys, coatis, toucans, ocellated turkeys and many of the reserve''s 400+ birds — jaguars and the five cat species exist but are rarely seen. Keep distance and never feed the monkeys, which can be aggressive around food.","source":"livinginguatemala.com, 2026-07-06","si_tag":"wildlife","accessed":"2026-07-06"},{"q":"When is the best time to visit Tikal?","a":"The dry season (roughly Nov–April) gives reliable sunrise views; January is the sweet spot — dry, cooler, wildlife active, and ahead of the Feb–April crowd wall — because the wettest months (Sep–Oct) bring muddy trails and Semana Santa (Holy Week) tightens Flores beds hard. Book lodges 8–12 weeks ahead for Holy Week.","source":"livinginguatemala.com, 2026-07-06","si_tag":"planning","accessed":"2026-07-06"}],"seo":{"meta_title":"Tikal & Flores, Guatemala Travel Guide — Maya Sunrise, Petén Jungle & Lake Petén Itzá | TravelWell.World","meta_description":"Climb Temple IV at sunrise, base on the painted island of Flores, and explore Yaxhá, Uaxactún and the Petén jungle — how to visit Tikal well, safely, and at the right time.","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en, es-GT","local_keywords":["tour Tikal desde Flores","amanecer Templo IV Tikal","atardecer en Yaxhá","Uaxactún observatorio astronómico","qué hacer en Flores Petén","Lago Petén Itzá atardecer","Biotopo Cerro Cahuí El Remate","entrada Parque Nacional Tikal precio"],"hreflang":["en","es-GT"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-08-20T14:47:53Z","source_updated":"2026-08-13T14:45:16+01:00"}]},"long_tail":["Tikal sunrise tour from Flores","Temple IV sunrise Tikal","Tikal vs Yaxhá sunset","best time to visit Tikal 2026","Flores Guatemala boutique hotels Lake Petén Itzá","Tikal malaria dengue precautions","Uaxactún equinox observatory tour","Cerro Cahuí El Remate hike"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"}],"ultra":[{"name":"Las Lagunas Boutique Hotel","why_ultra":"300-acre private nature reserve on Lake Quexil, two monkey islands, spa, on-site Maya-artifact museum, private jacuzzis + lake-view rooms; minutes from Tikal/Yaxhá/Uaxactún — the most complete luxury base in Petén.","earning":"consortia/agent rate + amenity block; agent-of-record commission","virtuoso_value_add":"upgrade, breakfast, resort/spa credit, early/late, VIP welcome (confirm current program)","mor":"Fora / host-IATA agent-of-record","tier":"luxury"},{"name":"La Lancha (Francis Ford Coppola)","why_ultra":"Coppola-family lodge on a rainforest hillside over Lago Petén Itzá; sunset-terrace bar, pools/hot tubs, brand cachet across the water from Flores.","earning":"consortia/agent rate; Family Coppola Hideaways trade terms","virtuoso_value_add":"amenity/credit + upgrade where program allows (verify)","mor":"Fora / host-IATA","tier":"luxury (boutique 4-star)"},{"name":"Bolontiku Boutique Hotel & Spa","why_ultra":"Boat-in lakefront boutique + spa on Lake Petén Itzá (15–30 min from Flores) — the arrive-by-boat seclusion play.","earning":"direct/consortia agent rate","virtuoso_value_add":"boat transfer + spa credit where negotiable (verify)","mor":"host-IATA agent-of-record","tier":"premier / luxury"}],"source_verified":"2026-07-06","hero":{"query":"Tikal / Flores, Guatemala"},"geo":{"lat":17.222,"lng":-89.6237},"orbit":[{"id":"antigua-guatemala","jewels":12,"si":["expedition","culture","culinary","wildlife"]},{"id":"guatemala-city-guatemala","jewels":9,"si":["culture"]},{"id":"lake-atitlan-guatemala","jewels":11,"si":["adventure","romance","culture","wellness"]},{"id":"semuc-champey-guatemala","jewels":6,"si":["expedition"]}],"orbit_country":[]}'::jsonb, 118),
