 Parián Tlaquepaque","is Guadalajara safe 2026"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Quinta Don José Boutique Hotel (Tlaquepaque Centro)","why_ultra":"Not ultra — anchor boutique (pool/spa/gallery/restaurant); accurate tier comfort–premier","earning":"host/GDS commission on application","virtuoso_value_add":"n/a (verify; not a Virtuoso flagship)","mor":"hotel"},{"name":"Nearest true ultra = Guadalajara city luxury / Puerto Vallarta (Hotel Mousai, villas)","why_ultra":"No ultra flagship in Tlaquepaque; nearest ultra is GDL metro or PV resort, same carve-out family","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Tlaquepaque, Mexico"},"geo":{"lat":20.6409,"lng":-103.2938},"orbit":[{"id":"careyes-mexico","jewels":7,"si":["ultra","romance","ocean"]},{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture","senior"]},{"id":"costalegre-mexico","jewels":7,"si":["tropical","romance","ultra","ocean"]},{"id":"guadalajara-mexico","jewels":8,"si":["culture","culinary","entertainment","sports"]},{"id":"mazamitla-mexico","jewels":6,"si":["expedition","family","adventure"]},{"id":"puerto-vallarta-mexico","jewels":5,"si":["romance","expedition","ocean"]},{"id":"san-sebastian-del-oeste-mexico","jewels":6,"si":["culture","expedition","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","celestun-mexico","chichen-itza-mexico","coba-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mah